use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf}};const R:&str="/home/ubuntu/src/zopro-perf-work/bundle-proof-pgo176";fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn files(p:&Path)->Vec<PathBuf>{let mut out=Vec::new();for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){out.extend(files(&e.path()));}else{out.push(e.path());}}out}
fn main(){assert!(!r("audit-recovery-plan.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(r("training-pins.json")).unwrap()).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let mut selected=Vec::new();for dir in["raw","training","training-proofs"]{selected.extend(files(&r(dir)));}for name in["merged.profdata","profile-counts.log","training-proof-inventory.json","profile-merge.stdout.log","profile-merge.stderr.log","profile-show.stderr.log","audit-recovery.rs","audit-recovery","audit-repair.md","make-recovery.rs","make-recovery.log","counts.rs","profile-inspect.rs","profile-inspect.jsonl","recovery-plan.rs","recovery-plan"]{selected.push(r(name));}for p in selected{pins.insert(p.display().to_string(),hash(&p));}fs::write(r("audit-recovery-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let p:Value=json!({"version":1,"source_pins":r("audit-recovery-pins.json"),"steps":[{"kind":"command","name":"review-retained-training","argv":[r("audit-recovery"),"finish"],"environment":{},"timeout_seconds":900}]});fs::write(r("audit-recovery-plan.json"),serde_json::to_vec_pretty(&p).unwrap()).unwrap();println!("Prepared independent one-command training-audit recovery; reused108successful captures/verifiers and completed merge/show outputs");}
